"""Explain timeout numbers and completion tokens, reset and lifetime."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1505': ('준비물을 기다릴 시간을 눈금 다섯 칸으로 정했다고 생각해 봅시다. 시간도 끝나고 준비물도 도착했다면 “못 받음”과 구별할 표시가 필요합니다.', '시간 제한 대기의 양수·0·음수와 경계 성공 표시를 구별합니다.', '남은 시간 3·조건 참 → 3, 남은 시간 0·조건 참 → 1, 남은 시간 0·조건 거짓 → 0의 세 줄 표를 적으세요.', ['swait의 timeout은 기다리는 시간의 제한입니다. 시간 인자는 jiffies라는 커널 시간 눈금 단위입니다. 숫자 5가 반드시 5초는 아닙니다. 눈금의 길이는 설정에 따라 달라지므로 초 단위 숫자와 그대로 섞지 않습니다.', '내부 대기 명령은 __ret = schedule_timeout(__ret)입니다. __ret에 남은 시간을 담고, 그만큼 기다린 뒤 돌아온 남은 시간으로 갱신합니다. 예를 들어 처음 5에서 일찍 깨어 남은 값이 3이라면 다음 기다림도 3을 사용합니다. 매번 5로 새로 시작하지 않습니다.', '___wait_cond_timeout은 조건과 남은 시간을 함께 판단하는 공통 도우미입니다. 조건이 참이고 남은 값도 3이면 성공 결과 3을 유지합니다. 조건이 거짓이고 값이 0이면 기다릴 시간이 끝난 것이므로 결과는 0입니다.', '조건이 참인데 남은 값이 0이면 도우미가 1로 바꿉니다. 이것은 성공을 0인 시간 만료와 구별하려는 표시입니다. 그래서 반환값 1만 보고 정확히 한 눈금이 남았거나 정확히 몇 눈금 동안 잠들었는지 단정할 수 없습니다.', 'interruptible timeout은 신호로 중단될 때 -ERESTARTSYS라는 음수도 반환할 수 있습니다. 결과는 양수이면 조건 성공, 0이면 조건 미충족 만료, 해당 음수이면 신호 중단으로 나눕니다. C의 if(ret)는 양수와 음수를 모두 참으로 보므로 성공 검사로 충분하지 않습니다.', '일반·interruptible·idle 변형은 대기 상태가 다르지만 이 시간 도우미를 공유합니다. 처음 조건이 참이거나 이미 시간 0으로 끝나면 내부 등록을 건너뛸 수 있습니다. 공통 반복에서도 조건·만료 도우미를 신호 오류보다 먼저 보므로, 조건 거짓·시간 0으로 끝난 판정을 무조건 신호 오류로 바꾸어 읽지 마세요.'], [('남은 시간이 0인데 조건은 참이에요. 성공과 시간 만료를 구별하려고 어떤 값을 돌려주나요?', ['언제나 0이에요', '성공 표시 1이에요'], '도우미는 조건이 참이고 __ret가 0이면 __ret를 1로 바꿉니다. 0은 조건을 만족하지 못한 시간 만료에 남겨 둬요. 여기의 1이 정확한 잔여 시간 측정값이라고 단정하면 안 됩니다.'), ('interruptible timeout의 결과가 -ERESTARTSYS예요. 0이 아니니 성공일까요?', ['아니요. 신호로 중단되었다는 음수 오류예요', '네. 0이 아닌 모든 값은 조건 성공이에요'], '이 함수에서 성공은 양수입니다. if(ret)만 쓰면 음수도 참이므로 실패를 성공으로 섞게 돼요. 양수, 0, 음수를 각각 나누어 확인하세요.')]), 'os1506': ('완료 도장을 하나 찍어 두면 나중에 온 사람도 그 도장을 확인하고 지나갈 수 있다고 해 봅시다. 그때 기다리는 사람이 없었다고 도장이 사라지는 것은 아닙니다.', 'completion의 완료 표시와 대기 줄이 서로 다른 정보를 담는다는 것을 이해합니다.', 'done=0에서 complete 두 번이면 2, 기다리는 작업이 하나씩 성공하며 사용하면 1, 0이라고 적으세요. 대기자 수는 별도 칸에 쓰세요.', ['completion은 다른 작업의 완료 알림을 기다리는 커널 도구입니다. struct completion에는 unsigned int done과 swait_queue_head wait가 있습니다. done은 완료 표시를 담는 음수 없는 정수이고 wait는 기다리는 작업들의 줄입니다.', '보통 done=0이면 아직 사용할 완료 표시가 없습니다. complete가 호출되면 표시를 하나 늘립니다. 대기 쪽이 완료를 확인하고 성공으로 지나가면 보통 표시를 하나 소비합니다. 소비한다는 것은 done을 하나 줄인다는 뜻입니다.', '예를 들어 초기 0에서 complete를 두 번 하면 2입니다. 이후 두 번의 성공적인 기다림이 각각 하나씩 사용하면 1, 0으로 바뀝니다. 이 값이 잠든 작업의 수를 세는 것은 아닙니다. 아무도 줄에 없어도 완료 표시가 남을 수 있습니다.', 'UINT_MAX는 unsigned int가 표현하는 가장 큰 값이며 특별한 완료 상태로 씁니다. complete_all은 이 값을 설정합니다. 이 상태에서는 대기자가 성공할 때 일반 표시처럼 하나씩 줄이지 않습니다. 올바르게 재설정하기 전까지 완료 상태가 유지된다는 의미이지 객체가 영원히 살아 있다는 뜻은 아닙니다.', 'wait 안의 raw 잠금은 done 변경과 대기 줄 연결을 보호합니다. completion 자체가 mutex처럼 특정 작업에게 잠금 소유권을 넘기는 도구는 아닙니다. “일이 끝났다는 표시”와 “공유 자료를 독점할 권리”는 다른 약속입니다.', 'complete가 기다리는 호출보다 먼저 와도 done에 표시가 저장됩니다. 그래서 나중 호출자가 그 표시를 사용할 수 있습니다. 단순히 지금 있는 대기자에게 깨움 요청만 보내는 것과 다른 점입니다. 실제 결과 자료도 필요한 기간 동안 유효해야 하고, 완료 알림은 결과가 준비된 뒤 보내야 합니다.'], [('completion의 done은 무엇을 세거나 표시하나요?', ['항상 지금 잠든 작업의 정확한 수예요', '사용할 수 있는 완료 표시와 특별한 완료 상태예요'], 'done은 일반적으로 완료 표시를 늘리고 소비하는 데 씁니다. UINT_MAX는 소비해 줄이지 않는 특별한 상태예요. 대기자가 없어도 complete로 done이 늘 수 있으므로 잠든 사람 수와 같지 않습니다.'), ('아직 아무도 기다리지 않을 때 complete를 먼저 불렀어요. 완료 표시를 잃나요?', ['아니요. 저장된 표시를 나중 대기자가 사용할 수 있어요', '네. 그 순간 대기자가 없으면 언제나 사라져요'], '완료 표시는 done에 남습니다. 나중 기다림이 그 표시를 사용하면 실제로 잠들 필요 없이 지나갈 수 있어요. 물론 그 사이 재설정이나 다른 소비가 없는 경우를 말합니다.')]), 'os1507': ('다음 놀이를 시작하며 도장 수만 0으로 바꾸는 것과, 도장판과 대기 명단을 모두 새로 만드는 것은 다릅니다. 사람이 기다리는 명단을 빈 종이로 바꾸면 그 사람들을 찾지 못할 수 있습니다.', '최초 초기화와 완료 표시만 재설정하는 동작의 차이를 배웁니다.', 'init은 done=0과 새 빈 줄, reinit은 done=0만 한다고 적으세요. 이미 줄에 A가 있는 상황에서 init으로 빈 줄을 만들면 어떤 문제가 생길지 설명하세요.', ['init_completion은 처음 사용할 completion을 준비합니다. 먼저 done을 0으로 만들고 init_swait_queue_head로 대기 줄의 잠금과 빈 연결을 초기화합니다. 아직 쓰지 않는 자료를 시작 상태로 만드는 일입니다.', 'reinit_completion은 이름이 비슷하지만 본문이 x->done = 0 하나입니다. 이미 준비된 완료 도구를 다음 사건에 재사용하려고 완료 표시를 지웁니다. 대기 줄의 연결과 잠금을 다시 초기화하지 않습니다.', '왜 사용 중인 자료에 init을 다시 하면 안 될까요? 예를 들어 A가 대기 줄에 있는데 head를 자기 자신만 가리키는 빈 줄로 바꾸면 A로 이어지는 연결을 잃을 수 있습니다. 함수가 기존 대기자를 새 줄로 옮기거나 알려 주는 작업은 하지 않습니다.', 'reinit은 줄을 지우지 않지만 동시 사용을 자동으로 안전하게 만드는 함수도 아닙니다. 다른 작업이 complete로 표시를 남기는 순간 done을 0으로 덮으면 필요한 알림을 지울 수 있습니다. 이전 사건과 다음 사건이 섞이지 않도록 호출자가 순서를 정해야 합니다.', '특히 complete_all 뒤 재사용할 때에는 이전 대기자들이 깨어나 일을 마쳤는지 확인해야 합니다. 완료 표시를 읽었다는 사실만으로 모든 대기자가 끝났다고 알 수는 없습니다. 관련 대기와 통지가 경쟁하지 않도록 하는 전체 규칙이 필요합니다.', '처음 만들 때에는 init, 재사용할 때에는 안전한 시점의 reinit으로 구별하세요. 둘 다 실행 중인 작업을 취소하거나 기다리는 작업을 자동으로 끝내 주는 명령이 아닙니다. 자료를 없애기 전에도 더 접근할 작업이 없는지 별도로 보장해야 합니다.'], [('reinit_completion은 줄과 잠금까지 새로 만들까요?', ['네. 모든 연결을 지워 빈 줄로 바꿔요', '아니요. done만 0으로 바꿔요'], '실제 본문은 x->done = 0입니다. init_swait_queue_head는 호출하지 않아요. 다만 줄을 보존한다는 사실이 다른 작업과 동시에 아무 때나 호출해도 된다는 뜻은 아닙니다.'), ('A가 기다리는 중에 init_completion을 다시 부르면 기존 등록이 안전하게 보존될까요?', ['아니요. 빈 줄로 초기화하면서 기존 연결을 잃을 수 있어요', '네. 기존 대기자를 자동으로 새 줄에 옮겨요'], 'init은 새 빈 head를 준비합니다. 기존 항목을 옮기는 동작이 없으므로 기다리는 작업이 줄에서 보이지 않게 될 수 있어요. 초기화를 작업 취소나 복구 명령으로 사용하면 안 됩니다.')]), 'os1508': ('잠깐 쓰는 책상 위에 연락장을 두고 친구에게 그 위치를 알려 줬다고 해 봅시다. 내가 기다리기를 그만두고 책상을 치워도 친구가 나중에 그곳에 쓰러 올 수 있습니다. 기다림 종료와 연락장 사용 종료는 다릅니다.', '스택 completion의 초기화와 실제 자료 수명을 구별합니다.', '대기 시작 → 시간 초과 → 함수 반환 → 늦은 complete의 순서를 그리세요. 자료를 더는 쓸 수 없는 시점과 늦은 접근 사이에 위험 표시를 하세요.', ['스택은 함수 실행에 필요한 지역 자료를 두는 공간입니다. 그 함수의 사용 범위가 끝나면 지역 completion도 더 이상 접근할 수 있는 자료로 남는다고 보장할 수 없습니다. 주소를 다른 작업에게 알려 주었다고 자동으로 사용 기간이 늘어나지는 않습니다.', 'DECLARE_COMPLETION은 done=0과 빈 swait head를 갖춘 completion을 선언합니다. 함수 안의 자동 지역 변수에는 DECLARE_COMPLETION_ONSTACK을 사용하도록 원문이 안내합니다. ONSTACK은 스택에서 사용하는 선언이라는 뜻입니다.', 'CONFIG_LOCKDEP가 켜져 있으면 ONSTACK은 실행 중 init_completion을 거쳐 잠금 검사에 필요한 초기화를 마련합니다. lockdep는 잠금 사용 문제를 찾는 검사 기능입니다. 이 설정이 꺼져 있으면 일반 선언으로 이어집니다. 어느 쪽도 다른 작업이 끝날 때까지 메모리를 붙잡아 주는 기능은 아닙니다.', 'MAP이 붙은 변형도 이 헤더의 초기화 규칙을 따릅니다. init_completion_map은 여기서 init_completion으로 이어집니다. 이름에 map이 있다고 별도의 장기 보관 공간이나 자동 취소 기능을 만든다고 추측하면 안 됩니다.', '예를 들어 A가 스택 completion의 주소를 B에게 주고 기다리다가 시간 초과로 먼저 돌아왔다고 해 봅시다. 이후 B가 complete를 부르면 이미 유효하지 않은 주소에 접근할 수 있습니다. 신호로 대기가 중단된 경우도 같은 수명 문제를 살펴야 합니다.', '따라서 함수가 반환하기 전 관련 작업의 완료나 취소 후 종료를 확인해 더 접근하지 않도록 해야 합니다. 설계에 따라 더 오래 살아 있는 자료 안에 completion을 둘 수도 있지만 그 자료 역시 마지막 사용자보다 먼저 없애면 안 됩니다. ONSTACK 선언, 대기 종료, 작업 취소, 모든 사용자의 종료는 각각 다른 일입니다.'], [('ONSTACK으로 선언하면 시간 초과 뒤에도 다른 작업이 끝날 때까지 메모리를 자동으로 유지하나요?', ['네. 이름에 ONSTACK이 있으면 계속 보관돼요', '아니요. 호출자가 모든 사용이 끝나는 시점을 보장해야 해요'], '매크로는 선언과 필요한 초기화를 합니다. 지역 자료의 수명을 자동 연장하지 않아요. 기다림에서 돌아왔다고 뒤늦게 complete할 작업까지 끝났다고 볼 수 없습니다.'), ('시간 제한이 끝나 기다림이 반환했어요. 다른 작업의 나중 complete도 자동으로 취소될까요?', ['아니요. 다른 작업의 종료와 접근을 따로 정리해야 해요', '네. 기다림 반환이 다른 작업을 삭제해요'], '시간 초과는 기다리는 쪽이 기다림을 끝낸 결과입니다. 다른 작업이 실행을 멈추거나 저장한 주소를 버렸다는 뜻은 아니에요. 객체를 없애기 전에 관련 사용이 끝났음을 보장해야 합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_372.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
